#!/usr/bin/env python3
"""Build a local-only, consent-aware practice surface from the mobile payload."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAYLOAD = ROOT / "research/communication-job-mobile-lessons.json"
CURRICULUM = ROOT / "research/communication-job-curriculum-index.json"
OUT = ROOT / "writeups/communication-job-practice.html"


def main() -> int:
    payload = json.loads(PAYLOAD.read_text())
    curriculum = json.loads(CURRICULUM.read_text())
    phrase_forms = {
        lesson["canonical_job"]: [item["phrase_form"] for item in lesson.get("phrase_forms", [])]
        for lesson in curriculum["lessons"]
    }
    lessons = [
        dict(lesson, indexed_phrase_forms=phrase_forms.get(lesson["canonical_job"], []))
        for lesson in payload["lessons"]
    ]
    data = json.dumps(lessons, ensure_ascii=False).replace("</", "<\\/")
    options = "".join(
        f'<option value="{i}">{lesson["canonical_job"]}</option>'
        for i, lesson in enumerate(lessons)
    )
    document = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Communication Patterns Lab — Practice</title><style>:root{font-family:system-ui,sans-serif;color:#17202a;background:#f5f3ee}body{margin:0}header{background:#17212b;color:#fff;padding:24px max(20px,calc((100vw - 1050px)/2))}main{max-width:1050px;margin:20px auto;padding:0 20px 60px}.notice{background:#fff7d6;border:1px solid #d8bd61;border-radius:8px;padding:14px}.panel{background:#fff;border:1px solid #d7d0c5;border-radius:9px;padding:16px;margin:16px 0}label{display:block;margin:.7rem 0}select,input,textarea{font:inherit;padding:.55rem;box-sizing:border-box;max-width:100%}select,input{width:min(100%,520px)}textarea{width:100%;min-height:85px}button{font:inherit;padding:.7rem 1rem;margin:.5rem .5rem .5rem 0;cursor:pointer}.example,.delivery{background:#f4f8fb;border-left:4px solid #39739d;padding:10px;margin:10px 0}.delivery{border-left-color:#856404;background:#fffaf0}video{display:block;max-width:100%;width:640px;margin:10px 0}.step{border-top:1px solid #e1e5e8;padding-top:12px;margin-top:12px}.muted{color:#5c6872;font-size:.9rem}.error{color:#9b1c1c;font-weight:600}a{color:#075985}</style></head><body><header><h1>Communication Patterns Lab — Practice</h1><p>Local rehearsal for provisional communication-job lessons.</p></header><main><div class="notice"><b>Boundary:</b> These are practice hypotheses, not proven best practices. This page does not upload responses, require recording or measure effectiveness. Do not imitate a speaker’s identity, accent, personality or mannerism. Use typed, spoken, captioned or asynchronous practice.</div><section class="panel"><label>Choose a communication job <select id="lesson">__OPTIONS__</select></label><p id="status" class="muted"></p><div id="content"></div></section><section class="panel"><h2>Save a local practice record</h2><p class="muted">Use a pseudonymous code. Saving downloads JSON to your device; nothing is sent to this repository.</p><label>Pseudonymous participant code <input id="participant" autocomplete="off" placeholder="e.g. learner-01"></label><label>Accessibility or modality note (optional) <textarea id="accessibility" rows="2"></textarea></label><label><input id="consent" type="checkbox"> I consent to save this local practice record for my own learning log.</label><p id="error" class="error" aria-live="polite"></p><button id="download" type="button">Download local practice JSON</button></section></main><script id="lesson-data" type="application/json">__DATA__</script><script>const lessons=JSON.parse(document.getElementById('lesson-data').textContent),select=document.getElementById('lesson'),content=document.getElementById('content'),status=document.getElementById('status'),error=document.getElementById('error');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const list=v=>Array.isArray(v)?v.map(esc).join('; '):esc(v);let currentResponses={};function renderDelivery(sample){const raw=sample.raw_media_state==='raw_audio_video_present';const media=raw?'<video controls preload="metadata" src="../data/video/'+encodeURIComponent(sample.video_id)+'.mp4"><a href="'+esc(sample.source_url)+'" target="_blank" rel="noopener">Open source context</a></video>':'<p><a href="'+esc(sample.source_url)+'" target="_blank" rel="noopener">Open source context</a> (raw local media unavailable)</p>';return '<div class="delivery"><b>'+esc(sample.sample_id)+'</b> — '+esc(sample.title)+'<p>'+esc(sample.transcript_excerpt)+'</p>'+media+'<p class="muted"><b>Status:</b> '+esc(sample.observation_status)+' · '+esc(sample.measurement_status)+' · matched feature segments: '+esc(sample.matched_feature_segment_count)+'</p><p class="muted"><b>Limits:</b> '+list(sample.measurement_limits)+'</p><p class="muted">Raw media is provided for personal inspection. Internal observations are not independent review, manual vocal listening or evidence of effectiveness.</p></div>'}function render(){const x=lessons[Number(select.value)];currentResponses={};status.textContent=x.status+' · claim level: '+x.claim_level;content.innerHTML='<h2>'+esc(x.canonical_job)+'</h2><p><b>Communication problem:</b> '+esc(x.communication_problem)+'</p><p><b>Why it might help:</b> '+esc(x.mechanism_hypothesis)+'</p><p><b>Repeatable form:</b> '+esc(x.repeatable_form)+'</p><h3>Indexed phrase forms</h3><p class="muted">These are transcript-retrieval families, not scripts or independently validated best practices.</p><p>'+((x.indexed_phrase_forms||[]).map(esc).join(' · ')||'No direct phrase-form family match indexed.')+'</p><h3>Inspect exact examples</h3>'+x.exact_examples.slice(0,3).map(e=>'<div class="example"><a href="'+esc(e.source_url)+'" target="_blank" rel="noopener">Open source context</a><p>'+e.segments.map(s=>'<b>'+esc(s.evidence_id)+'</b> '+esc(s.text)).join(' ')+'</p></div>').join('')+'<h3>Delivery samples (manual/independent review pending)</h3>'+x.delivery_samples.map(renderDelivery).join('')+x.steps.map((step,i)=>'<div class="step"><h3>'+(i+1)+'. '+esc(step.type)+'</h3><p>'+esc(step.prompt)+'</p><textarea data-step="'+esc(step.step_id)+'" aria-label="Response for '+esc(step.step_id)+'" placeholder="Your response (optional unless marked required)"></textarea></div>').join('')+'<p class="muted"><b>Safety:</b> '+esc(x.safety_boundary)+'</p>}function gather(){const r={};document.querySelectorAll('[data-step]').forEach(e=>r[e.dataset.step]=e.value);return r}select.onchange=render;document.getElementById('download').onclick=()=>{error.textContent='';const participant=document.getElementById('participant').value.trim();if(!participant||!document.getElementById('consent').checked){error.textContent='Enter a pseudonymous code and give explicit consent before saving.';return}const x=lessons[Number(select.value)],record={schema_version:'1.0',record_type:'local_communication_practice_record',claim_boundary:'Local practice log only; not learner-validation evidence or effectiveness evidence.',lesson_id:x.lesson_id,pattern_id:x.pattern_id,canonical_job:x.canonical_job,participant_code:participant,consent:true,accessibility_or_modality:document.getElementById('accessibility').value,step_responses:gather(),source_payload:'research/communication-job-mobile-lessons.json',saved_at:new Date().toISOString()};const blob=new Blob([JSON.stringify(record,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='communication-practice-'+x.canonical_job+'.json';a.click();URL.revokeObjectURL(url)};render();</script></body></html>""".replace("__OPTIONS__", options).replace("__DATA__", data)
    # Keep the generated browser script valid after the template is rendered.
    document = document.replace("+'</p>}function gather", "+'</p>'}function gather")
    document = document.replace("+'\n'", "+'\\n'")
    OUT.write_text(document)
    print(f"wrote {OUT.relative_to(ROOT)} ({len(lessons)} lessons)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
